$(document).ready(function () {

  // Custom regex method for email format
  $.validator.addMethod("patternEmail", function(value, element) {
    return this.optional(element) || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
  }, "Please enter a valid email address format.");

  // Custom placement to put errors directly into your existing data-error-for span elements
  const customErrorPlacement = function(error, element) {
    const errorSpan = $('span[data-error-for="' + element.attr('name') + '"]');
    if (errorSpan.length) {
      errorSpan.text(error.text()); // Inject error message directly next to the label
    } else {
      error.insertAfter(element);
    }
  };

  const customSuccess = function(label, element) {
    const errorSpan = $('span[data-error-for="' + $(element).attr('name') + '"]');
    if (errorSpan.length) {
      errorSpan.text("");
    }
  };

  $("#userForm").validate({
    errorElement: 'span',
    errorPlacement: customErrorPlacement,
    success: customSuccess,
    rules: {
      name: "required",
      email: {
        required: true,
        patternEmail: true,
        remote: {
          url: "check-email.php",
          type: "post",
          data: { 
            email: function() { return $("input[name='email']").val(); } 
          }
        }
      },
      password: "required",
      country: "required",
      state: "required",
      city: "required"
    },
    messages: {
      email: {
        remote: "This email is already in use. Please select another one."
      }
    }
  });

 

  // Clear errors when modals are hidden
  $('.modal').on('hidden.bs.modal', function() {
    const form = $(this).find('form');
    if (form.length && form.validate) {
      let validator = form.validate();
      if(validator) validator.resetForm();
      form.find('span[data-error-for]').text('');
    }
  });

});